"use strict";
// Type Aliases in TypeScript
const add = (x, y) => {
    return x + y;
};
console.log(add(5, 10)); // Output: 15
let userId = "user123";
userId = 456;
console.log(userId); // Output: 456
let employee = {
    name: "John Doe",
    age: 30,
    employeeId: 123,
    department: "Engineering",
    salary: 50000
};
console.log(employee);
